receivers.before:
.wearable-strip {
  margin: 20px 0 8px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px 12px;
  /* On mobile the chat + import FABs sit at the bottom-right and overlap the
     last strip card. Reserve enough bottom margin so the FABs don't obscure
     readings. (Desktop FAB is smaller and the strip isn't bottom-anchored.) */
  box-shadow: var(--shadow);
}

receivers.after:
.wearable-strip /* On mobile the chat + import FABs sit at the bottom-right and overlap the
     last strip card. Reserve enough bottom margin so the FABs don't obscure
     readings. (Desktop FAB is smaller and the strip isn't bottom-anchored.) */ {
  margin: 20px 0 8px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px 12px;
  box-shadow: var(--shadow);
}

receivers.before:
.wearable-strip {
    margin-bottom: 80px; /* room for chat FAB + import FAB stacked */
  }

receivers.after:
.wearable-strip /* room for chat FAB + import FAB stacked */ {
  margin-bottom: 80px;
}

receivers.before:
.wearable-card-grid {
  display: grid;
  /* auto-fit so the grid stays even no matter how many cards the adapter
     registry produces (4 for Oura basics, 8-9 with full scopes, more when
     WHOOP/Apple Health join). Cards want ~220px min; the row refills across
     the available width without leaving half-empty tail rows. */
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
}

receivers.after:
.wearable-card-grid /* auto-fit so the grid stays even no matter how many cards the adapter
     registry produces (4 for Oura basics, 8-9 with full scopes, more when
     WHOOP/Apple Health join). Cards want ~220px min; the row refills across
     the available width without leaving half-empty tail rows. */ {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
}

